.vent-modular{--vm-bg:#001827;--vm-panel:#01283d;--vm-panel-2:#001d2f;--vm-line:#075677;--vm-text:#f0f5ff;--vm-sub:#acc9e8;--vm-cyan:#00ecf6;--vm-ok:#00e7b5;--vm-warn:#ffbf19;--vm-danger:#ff484d;box-sizing:border-box;color:var(--vm-text);font:13px/1.42 Arial,"Helvetica Neue",sans-serif;background:radial-gradient(ellipse at 50% 0,#04334a 0,transparent 68%),var(--vm-bg);min-width:0;padding:12px}
.vent-modular *{box-sizing:border-box}.vent-modular :where(button,input,table){font:inherit}.vent-modular :where(button){color:inherit}.vent-modular :where(button,input){border:0}.vent-modular h1,.vent-modular h2,.vent-modular p{margin:0}.vent-modular h1{font-size:21px;line-height:1.2}.vent-modular h2{font-size:16px;line-height:1.25}.vent-modular small,.vent-modular .vm-muted{color:var(--vm-sub);font-size:12px}.vm-eyebrow{color:var(--vm-cyan);font-size:11px;font-weight:700;letter-spacing:.55px}.vm-header{margin-bottom:12px}.vm-header__line{display:flex;align-items:center;gap:12px;padding-bottom:9px;border-bottom:1px solid var(--vm-line)}.vm-header__scope{margin-left:auto;color:var(--vm-sub)}.vm-header__meta{display:flex;gap:10px;align-items:center;color:var(--vm-sub)}.vm-header--home{display:flex;justify-content:space-between;align-items:end;gap:16px;padding-bottom:9px;border-bottom:1px solid var(--vm-line)}.vm-badge{padding:3px 7px;border:1px solid var(--vm-warn);border-radius:4px;color:var(--vm-warn);font-size:11px;white-space:nowrap}.vm-back{padding:7px 10px;border:1px solid var(--vm-cyan)!important;border-radius:4px;background:#003149;color:var(--vm-cyan);cursor:pointer;white-space:nowrap}.vm-tabs{display:flex;gap:6px;overflow-x:auto;padding-top:8px}.vm-tabs button,.vm-settings-tabs button{padding:8px 11px;background:transparent;color:var(--vm-sub);cursor:pointer;white-space:nowrap}.vm-tabs .is-active,.vm-settings-tabs .is-active{border-bottom:2px solid var(--vm-cyan)!important;color:var(--vm-cyan);background:#00314988}.vm-overview,.vm-controller,.vm-alarms{display:grid;gap:12px}.vm-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.vm-card,.vm-panel{min-width:0;border:1px solid var(--vm-line);border-radius:6px;background:linear-gradient(115deg,var(--vm-panel),var(--vm-panel-2));box-shadow:inset 0 1px #2e779019}.vm-card{min-height:92px;padding:12px}.vm-card>p{color:var(--vm-sub);font-size:13px}.vm-card>b{display:block;margin:4px 0 1px;font-size:24px;font-variant-numeric:tabular-nums}.vm-card>b small{font-size:15px;font-weight:500}.vm-card--ok{border-color:#008b74}.vm-card--warn{border-color:#84651a}.vm-card--danger{border-color:#88343a}.vm-panel{padding:12px}.vm-panel__head{display:flex;justify-content:space-between;gap:12px;align-items:start;padding-bottom:10px;border-bottom:1px solid var(--vm-line)}.vm-panel__head p{margin-top:3px;color:var(--vm-sub);font-size:12px}.vm-search{display:flex;align-items:center;gap:6px;color:var(--vm-sub);font-size:12px;white-space:nowrap}.vm-search input{width:170px;padding:6px 8px;border:1px solid var(--vm-line);border-radius:4px;background:#001927;color:var(--vm-text)}.vm-search input:focus{outline:2px solid var(--vm-cyan)}.vm-barn-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:10px}.vm-barn{min-height:102px;padding:10px;border:1px solid var(--vm-line)!important;border-radius:5px;background:#001b2c;text-align:left;cursor:pointer}.vm-barn:hover,.vm-barn:focus-visible{outline:2px solid var(--vm-cyan);outline-offset:-2px}.vm-barn>b,.vm-barn>span{display:block}.vm-barn>b{font-size:15px;margin-bottom:6px}.vm-barn>b small{margin-left:4px;color:var(--vm-warn);font-size:9px}.vm-barn>span{font-size:12px}.vm-status--RUNNING,.vm-status--ONLINE,.vm-status--CURRENT,.vm-status--NORMAL{color:var(--vm-ok)}.vm-status--STALE,.vm-status--WARNING{color:var(--vm-warn)}.vm-status--OFFLINE,.vm-status--MAJOR,.vm-status--ACTIVE{color:var(--vm-danger)}.vm-status--UNKNOWN,.vm-status--NOT_CONFIGURED{color:var(--vm-sub)}.vm-empty,.vm-notice{margin-top:10px;padding:9px;border-left:3px solid var(--vm-warn);background:#3a2e0d55;color:var(--vm-sub)}.vm-flags{display:flex;gap:7px;flex-wrap:wrap;margin:9px 0}.vm-flags>span{padding:4px 7px;border:1px solid var(--vm-line);border-radius:4px;background:#001827;font-size:12px}.vm-house{min-width:720px;padding:16px;border:1px solid #064862;border-radius:5px;background:radial-gradient(ellipse at center,#06436066,#001824 85%);overflow:hidden}.vm-synoptic{overflow:auto}.vm-house__roof{height:28px;margin:0 8% 12px;clip-path:polygon(50% 0,100% 100%,0 100%);background:linear-gradient(#79abc6,#244c65)}.vm-fans{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;padding:16px;border:2px solid #527c95;border-bottom:0}.vm-pumps{display:flex;gap:12px;padding:10px 20%;border:2px solid #527c95;border-top:0}.vm-device{min-width:0;text-align:center}.vm-device__glyph{display:block;width:38px;height:38px;margin:0 auto 5px;border:2px solid currentColor;border-radius:50%;background:radial-gradient(circle,#0b5a70 0 18%,transparent 20%),repeating-conic-gradient(#6594ae 0 13deg,transparent 14deg 60deg)}.vm-device__glyph.pump{border-radius:4px;background:#053c43}.vm-device b,.vm-device small{display:block;font-size:11px}.vm-louvers{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:10px}.vm-louvers>div{display:grid;grid-template-columns:125px 1fr auto;align-items:center;gap:8px;font-size:12px}.vm-louvers span{height:10px;border:1px solid var(--vm-line);background:#001827}.vm-louvers i{display:block;height:100%;background:var(--vm-cyan)}.vm-controller{grid-template-columns:repeat(2,minmax(0,1fr))}.vm-summary{display:grid;gap:6px;margin:10px 0 0}.vm-summary>div{display:flex;justify-content:space-between;gap:10px;padding:8px;background:#001927;border:1px solid var(--vm-line);border-radius:4px}.vm-summary dt{color:var(--vm-sub)}.vm-summary dd{margin:0;text-align:right;font-weight:700}.vm-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px;margin-top:10px}.vm-metrics>div{min-height:75px;padding:8px;border:1px solid var(--vm-line);border-radius:4px;background:#001927}.vm-metrics small,.vm-metrics b,.vm-metrics em{display:block}.vm-metrics b{margin:3px 0;font-size:16px}.vm-metrics em{color:var(--vm-sub);font-size:10px;font-style:normal}.vm-chart-wrap,.vm-table-wrap{overflow:auto;margin-top:10px}.vm-chart{display:block;min-width:760px;width:100%;min-height:240px;background:#