@media(max-width:820px){.vm-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.vm-barn-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.vm-controller,.vm-alarms{grid-template-columns:1fr}.vm-header__scope{display:none}.vm-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:520px){.vent-modular{padding:8px}.vm-header--home{align-items:start;flex-direction:column}.vm-header__meta{width:100%;justify-content:space-between}.vm-header__line{align-items:start}.vm-panel__head{flex-direction:column}.vm-search{width:100%}.vm-search input{width:100%}.vm-barn-grid,.vm-settings-list{grid-template-columns:1fr}.vm-kpis{gap:7px}.vm-card{min-height:82px}.vm-card>b{font-size:20px}.vm-louvers{grid-template-columns:1fr}.vm-louvers>div{grid-template-columns:110px 1fr auto}}
@media(prefers-reduced-motion:reduce){.vent-modular *{scroll-behavior:auto!important}}
.vm-louver-cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;margin-top:8px}.vm-louver-cards>div{padding:7px;background:#001927;border:1px solid var(--vm-line);border-radius:4px}.vm-louver-cards b,.vm-louver-cards span,.vm-louver-cards small{display:block}
.vm-barn-svg{display:block;width:100%;height:auto;margin-top:10px;border:1px solid #064862;border-radius:5px;background:radial-gradient(ellipse at center,#06436066,#001824 85%)}.vm-svg-wall{fill:#032133;stroke:#537b93;stroke-width:3}.vm-svg-roof{fill:#356681;stroke:#88b2cb}.vm-svg-frame{fill:none;stroke:#739bb5;stroke-width:5}.vm-svg-louver rect{fill:#153d52;stroke:#709bb5;stroke-width:2}.vm-svg-louver path{fill:none;stroke:#8ab5cf;stroke-width:2}.vm-barn-svg text{fill:#f0f5ff;font-size:12px;text-anchor:middle}.vm-svg-louver text{fill:#acc9e8;font-size:11px}.vm-svg-fan rect{fill:#092b3e;stroke:#5b839b;stroke-width:2}.vm-svg-fan circle{fill:#001725;stroke:#00e7b5;stroke-width:2}.vm-svg-fan path{fill:#6594ae;stroke:#112c42}.vm-svg-pump path{fill:none;stroke:#00e7b5;stroke-width:2}.vm-svg-pump rect{fill:#053c43;stroke:#00e7b5;stroke-width:2}.vm-device-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;margin-top:10px}.vm-device-list>div{padding:8px;border:1px solid var(--vm-line);border-radius:4px;background:#001927}.vm-device-list b,.vm-device-list span,.vm-device-list small{display:block}.vm-nonpilot dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.vm-nonpilot dl>div{padding:8px;background:#001927;border:1px solid var(--vm-line)}.vm-nonpilot dt{color:var(--vm-sub)}.vm-nonpilot dd{margin:3px 0 0;font-weight:700}@media(max-width:520px){.vm-device-list,.vm-nonpilot dl{grid-template-columns:1fr}}

.vent-modular-root{height:100%;overflow:auto;overscroll-behavior:contain;min-width:0}
.vent-modular-root h1,.vent-modular-root h2,.vent-modular-root h3{font-weight:700;line-height:1.25}
.vent-modular-root p{line-height:1.42}
.vent-modular-root :where(b,strong){font-weight:700}
.vent-modular-root :where(table,th,td){font-family:inherit;font-size:inherit}
.vent-modular-root [hidden]{display:none!important}

